:root {
  /* Surface / Elevation */
  --color-bg: #f0f0f2;
  --color-surface: #ffffff;
  --color-surface-raised: #e4e4e7;
  --color-surface-overlay: #ffffff;
  --color-surface-sunken: #d4d4d8;
  --color-surface-inverse: #09090b;

  /* Text */
  --color-text: #09090b;
  --color-text-secondary: #3f3f46;
  --color-text-muted: #71717a;
  --color-text-disabled: #a1a1aa;
  --color-text-link: #09090b;
  --color-text-inverse: #f0f0f2;
  --color-text-link-hover: #ff3b00;
  --color-text-on-accent: #ffffff;

  /* Border / Divider */
  --color-border: #09090b;
  --color-border-subtle: #d4d4d8;
  --color-border-strong: #09090b;
  --color-divider: #e4e4e7;

  /* Accent / Brand */
  --color-accent: #ff3b00;
  --color-accent-hover: #d93200;
  --color-accent-active: #b32900;
  --color-accent-subtle: #fff0eb;
  --color-accent-muted: #ff9d80;
  --color-accent-border: #ff3b00;
  --color-accent-text: #d93200;
  --color-on-accent: #ffffff;
  --color-accent-secondary: #0f172a;
  --color-accent-secondary-subtle: #f1f5f9;

  /* Disabled / Inert */
  --color-surface-disabled: #e4e4e7;
  --color-border-disabled: #a1a1aa;
  --color-icon-disabled: #a1a1aa;

  /* Form / Input */
  --color-input-bg: #ffffff;
  --color-input-border: #09090b;
  --color-input-border-focus: #ff3b00;
  --color-input-placeholder: #71717a;
  --color-input-bg-hover: #fafafa;
  --color-input-bg-disabled: #e4e4e7;
  --color-input-border-hover: #3f3f46;
  --color-input-border-error: #dc2626;
  --color-input-text: #09090b;
  --color-input-icon: #3f3f46;

  /* Brand Scale (primitive) */
  --color-brand-50: #fff0eb;
  --color-brand-100: #ffdcd2;
  --color-brand-200: #ffb5a1;
  --color-brand-300: #ff886b;
  --color-brand-400: #ff5c33;
  --color-brand-500: #ff3b00;
  --color-brand-600: #d93200;
  --color-brand-700: #b32900;
  --color-brand-800: #8c2000;
  --color-brand-900: #661700;

  /* Neutral Scale */
  --color-neutral-50: #fafafa;
  --color-neutral-100: #f0f0f2;
  --color-neutral-200: #e4e4e7;
  --color-neutral-300: #d4d4d8;
  --color-neutral-400: #a1a1aa;
  --color-neutral-500: #71717a;
  --color-neutral-600: #52525b;
  --color-neutral-700: #3f3f46;
  --color-neutral-800: #27272a;
  --color-neutral-900: #09090b;
  --color-neutral-950: #040405;
  --color-neutral-1000: #000000;

  /* Data Visualization */
  --color-chart-1: #ff3b00;
  --color-chart-2: #0f172a;
  --color-chart-3: #2563eb;
  --color-chart-4: #059669;
  --color-chart-5: #d97706;
  --color-chart-6: #7c3aed;
  --color-chart-7: #db2777;
  --color-chart-8: #4b5563;
  --color-chart-grid: #d4d4d8;
  --color-chart-axis: #09090b;
  --color-chart-tooltip-bg: #09090b;

  /* Interaction */
  --color-focus-ring: #ff3b00;
  --color-hover-overlay: rgba(9, 9, 11, 0.04);
  --color-active-overlay: rgba(9, 9, 11, 0.08);
  --color-selected: #e4e4e7;
  --color-selected-subtle: #fff0eb;
  --color-pressed-overlay: rgba(9, 9, 11, 0.12);

  /* Semantic State */
  --color-success: #059669;
  --color-success-subtle: #ecfdf5;
  --color-success-muted: #6ee7b7;
  --color-success-border: #059669;
  --color-success-text: #047857;
  --color-on-success: #ffffff;
  --color-warning: #d97706;
  --color-warning-subtle: #fffbeb;
  --color-warning-muted: #fcd34d;
  --color-warning-border: #d97706;
  --color-warning-text: #b45309;
  --color-on-warning: #ffffff;
  --color-danger: #dc2626;
  --color-danger-subtle: #fef2f2;
  --color-danger-muted: #fca5a5;
  --color-danger-border: #dc2626;
  --color-danger-text: #b91c1c;
  --color-on-danger: #ffffff;
  --color-info: #2563eb;
  --color-info-subtle: #eff6ff;
  --color-info-muted: #93c5fd;
  --color-info-border: #2563eb;
  --color-info-text: #1d4ed8;
  --color-on-info: #ffffff;

  /* Alpha / Overlay */
  --color-scrim: rgba(9, 9, 11, 0.65);
  --color-shadow: rgba(9, 9, 11, 0.12);
  --color-tint-subtle: rgba(255, 59, 0, 0.04);

  /* Font Family */
  --font-sans: "Satoshi", "General Sans", -apple-system, sans-serif;
  --font-serif: "Instrument Serif", serif;
  --font-mono: "JetBrains Mono", "Fira Code", monospace;
  --font-display: "Syne", "Clash Display", sans-serif;

  /* Display Size */
  --font-size-display-xs: clamp(2rem, 3.5vw, 2.5rem);
  --font-size-display-sm: clamp(2.5rem, 4.5vw, 3.25rem);
  --font-size-display-md: clamp(3.25rem, 6vw, 4.25rem);
  --font-size-display-lg: clamp(4.25rem, 8vw, 5.75rem);
  --font-size-display-xl: clamp(5.5rem, 11vw, 7.5rem);

  /* Font Size */
  --font-size-xs: 0.75rem;
  --font-size-sm: 0.875rem;
  --font-size-base: 1rem;
  --font-size-lg: 1.125rem;
  --font-size-xl: 1.25rem;
  --font-size-2xl: 1.5rem;
  --font-size-3xl: 1.875rem;
  --font-size-4xl: 2.25rem;
  --font-size-5xl: 3rem;
  --font-size-6xl: 3.75rem;
  --font-size-7xl: 4.5rem;

  /* Font Weight */
  --font-weight-light: 300;
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Line Height */
  --line-height-tight: 1.05;
  --line-height-snug: 1.2;
  --line-height-normal: 1.45;
  --line-height-relaxed: 1.6;
  --line-height-none: 1;
  --line-height-loose: 1.75;

  /* Letter Spacing */
  --letter-spacing-tight: -0.03em;
  --letter-spacing-normal: 0em;
  --letter-spacing-wide: 0.04em;
  --letter-spacing-wider: 0.08em;
  --letter-spacing-tighter: -0.05em;

  /* Text Measure */
  --text-measure-xs: 30ch;
  --text-measure-sm: 42ch;
  --text-measure-md: 58ch;
  --text-measure-lg: 70ch;
  --text-measure-xl: 80ch;
  --text-measure-wide: 96ch;

  /* Spacing */
  --space-0: 0px;
  --space-px: 1px;
  --space-0-5: 0.125rem;
  --space-1: 0.25rem;
  --space-1-5: 0.375rem;
  --space-2: 0.5rem;
  --space-2-5: 0.625rem;
  --space-3: 0.75rem;
  --space-3-5: 0.875rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-7: 1.75rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-14: 3.5rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;
  --space-28: 7rem;
  --space-32: 8rem;
  --space-40: 10rem;
  --space-48: 12rem;
  --space-56: 14rem;
  --space-64: 16rem;
  --space-72: 18rem;
  --space-80: 20rem;
  --space-96: 24rem;

  /* Section Spacing */
  --section-space-xs: 2rem;
  --section-space-sm: 3.5rem;
  --section-space-md: 5.5rem;
  --section-space-lg: 7.5rem;
  --section-space-xl: 10rem;
  --section-space-2xl: 13rem;
  --section-space-3xl: 16rem;

  /* Border Radius */
  --radius-none: 0px;
  --radius-xs: 1px;
  --radius-sm: 2px;
  --radius-md: 2px;
  --radius-lg: 3px;
  --radius-xl: 4px;
  --radius-2xl: 6px;
  --radius-3xl: 8px;
  --radius-full: 9999px;

  /* Border Width */
  --border-width-none: 0px;
  --border-width-thin: 1px;
  --border-width-medium: 2px;
  --border-width-thick: 4px;

  /* Layout / Grid */
  --container-max-width-xs: 480px;
  --container-max-width-sm: 640px;
  --container-max-width-md: 768px;
  --container-max-width-lg: 1024px;
  --container-max-width-xl: 1280px;
  --container-max-width-2xl: 1536px;
  --container-padding-sm: 1rem;
  --container-padding-md: 1.5rem;
  --container-padding-lg: 2.5rem;
  --container-padding-xl: 3.5rem;
  --container-padding-2xl: 4.5rem;
  --grid-columns: 12;
  --grid-columns-sm: 4;
  --grid-columns-md: 8;
  --grid-columns-lg: 12;
  --grid-columns-xl: 12;
  --grid-gutter: 1.5rem;
  --grid-gutter-sm: 1rem;
  --grid-gutter-md: 1.25rem;
  --grid-gutter-lg: 1.75rem;
  --grid-gutter-xl: 2.25rem;
  --grid-margin-sm: 1rem;
  --grid-margin-md: 1.5rem;
  --grid-margin-lg: 2.5rem;
  --grid-margin-xl: 3.5rem;

  /* Composition */
  --composition-max-width: 1440px;
  --composition-max-width-wide: 1680px;
  --composition-max-width-narrow: 960px;
  --composition-gutter: 2rem;
  --composition-offset-sm: 1.5rem;
  --composition-offset-md: 3rem;
  --composition-offset-lg: 4.5rem;
  --composition-overlap-sm: -1.5rem;
  --composition-overlap-md: -3rem;
  --composition-overlap-lg: -4.5rem;
  --composition-aspect-wide: 21 / 9;
  --composition-aspect-standard: 16 / 9;
  --composition-aspect-square: 1 / 1;
  --composition-aspect-portrait: 3 / 4;

  /* Media */
  --media-radius: 0px;
  --media-radius-sm: 0px;
  --media-radius-lg: 2px;
  --media-radius-xl: 2px;
  --media-aspect-wide: 21 / 9;
  --media-aspect-video: 16 / 9;
  --media-aspect-standard: 4 / 3;
  --media-aspect-square: 1 / 1;
  --media-aspect-portrait: 3 / 4;
  --media-overlay: rgba(9, 9, 11, 0.4);
  --media-overlay-subtle: rgba(9, 9, 11, 0.15);
  --media-overlay-strong: rgba(9, 9, 11, 0.75);

  /* Sizes */
  --size-icon-xs: 0.875rem;
  --size-icon-sm: 1rem;
  --size-icon-md: 1.25rem;
  --size-icon-lg: 1.5rem;
  --size-icon-xl: 2rem;
  --size-control-xs: 1.75rem;
  --size-control-sm: 2.25rem;
  --size-control-md: 2.75rem;
  --size-control-lg: 3.25rem;
  --size-control-xl: 3.75rem;
  --size-avatar-xs: 1.5rem;
  --size-avatar-sm: 2rem;
  --size-avatar-md: 2.75rem;
  --size-avatar-lg: 3.5rem;
  --size-avatar-xl: 4.5rem;
  --size-header-height: 4rem;
  --size-header-height-mobile: 3.5rem;
  --size-sidebar-width: 18rem;
  --size-sidebar-width-collapsed: 4rem;

  /* Control Geometry */
  --control-padding-x-xs: 0.5rem;
  --control-padding-x-sm: 0.75rem;
  --control-padding-x-md: 1.25rem;
  --control-padding-x-lg: 1.75rem;
  --control-padding-x-xl: 2.25rem;
  --control-padding-y-xs: 0.25rem;
  --control-padding-y-sm: 0.375rem;
  --control-padding-y-md: 0.625rem;
  --control-padding-y-lg: 0.875rem;
  --control-padding-y-xl: 1.125rem;
  --control-radius: 2px;
  --control-border-width: 1px;
  --control-icon-gap: 0.5rem;

  /* Iconography */
  --icon-stroke-width-thin: 1px;
  --icon-stroke-width: 1.5px;
  --icon-stroke-width-medium: 2px;
  --icon-stroke-width-bold: 2.5px;
  --icon-gap-xs: 0.25rem;
  --icon-gap-sm: 0.375rem;
  --icon-gap-md: 0.5rem;

  /* Shadow / Elevation */
  --shadow-xs: 1px 1px 0px #09090b;
  --shadow-sm: 2px 2px 0px #09090b;
  --shadow-md: 4px 4px 0px #09090b;
  --shadow-lg: 6px 6px 0px #09090b;
  --shadow-xl: 8px 8px 0px #09090b;
  --shadow-2xl: 12px 12px 0px #09090b;
  --shadow-inner: inset 1px 1px 2px rgba(9, 9, 11, 0.1);
  --shadow-focus: 0 0 0 2px #f0f0f2, 0 0 0 4px #ff3b00;
  --shadow-outline: 0 0 0 1px #09090b;

  /* Glow / Light Effects */
  --glow-sm: 0 0 6px rgba(255, 59, 0, 0.25);
  --glow-md: 0 0 12px rgba(255, 59, 0, 0.3);
  --glow-lg: 0 0 20px rgba(255, 59, 0, 0.35);
  --glow-xl: 0 0 30px rgba(255, 59, 0, 0.4);

  /* Blur */
  --blur-sm: 0px;
  --blur-md: 0px;
  --blur-lg: 0px;
  --blur-xl: 0px;

  /* Gradient */
  --gradient-brand: linear-gradient(135deg, #ff3b00 0%, #b32900 100%);
  --gradient-brand-subtle: linear-gradient(180deg, #fff0eb 0%, #f0f0f2 100%);
  --gradient-surface: linear-gradient(180deg, #ffffff 0%, #f0f0f2 100%);
  --gradient-surface-subtle: linear-gradient(180deg, #e4e4e7 0%, #d4d4d8 100%);
  --gradient-glow: radial-gradient(circle at center, rgba(255, 59, 0, 0.15) 0%, transparent 70%);
  --gradient-fade: linear-gradient(180deg, rgba(240, 240, 242, 0) 0%, #f0f0f2 100%);
  --gradient-hero: linear-gradient(90deg, #09090b 0%, #27272a 100%);

  /* Opacity */
  --opacity-hover: 0.92;
  --opacity-disabled: 0.45;
  --opacity-active: 0.85;
  --opacity-selected: 1;
  --opacity-muted: 0.65;
  --opacity-overlay: 0.65;

  /* Duration */
  --duration-instant: 0ms;
  --duration-fast: 100ms;
  --duration-normal: 180ms;
  --duration-slow: 300ms;
  --duration-slower: 450ms;
  --duration-slowest: 700ms;

  /* Motion Distance */
  --motion-distance-xs: 2px;
  --motion-distance-sm: 4px;
  --motion-distance-md: 8px;
  --motion-distance-lg: 16px;
  --motion-distance-xl: 32px;

  /* Motion Scale */
  --motion-scale-hover: 1.005;
  --motion-scale-active: 0.985;
  --motion-scale-enter: 0.98;
  --motion-scale-exit: 0.99;

  /* Motion Blur */
  --motion-blur-enter: 0px;
  --motion-blur-exit: 0px;

  /* Easing */
  --ease-linear: cubic-bezier(0, 0, 1, 1);
  --ease-in: cubic-bezier(0.4, 0, 1, 1);
  --ease-out: cubic-bezier(0, 0, 0.2, 1);
  --ease-in-out: cubic-bezier(0.4, 0, 0.2, 1);
  --ease-spring: cubic-bezier(0.18, 0.89, 0.32, 1.28);
  --ease-bounce: cubic-bezier(0.34, 1.56, 0.64, 1);
  --ease-smooth: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-emphasized: cubic-bezier(0.2, 0, 0, 1);

  /* Semantic Motion */
  --motion-enter: transform 180ms cubic-bezier(0, 0, 0.2, 1), opacity 180ms cubic-bezier(0, 0, 0.2, 1);
  --motion-exit: transform 100ms cubic-bezier(0.4, 0, 1, 1), opacity 100ms cubic-bezier(0.4, 0, 1, 1);
  --motion-hover: background-color 100ms cubic-bezier(0, 0, 0.2, 1), border-color 100ms cubic-bezier(0, 0, 0.2, 1);
  --motion-press: transform 60ms cubic-bezier(0, 0, 0.2, 1);
  --motion-reveal: transform 300ms cubic-bezier(0.16, 1, 0.3, 1), opacity 300ms cubic-bezier(0.16, 1, 0.3, 1);
  --motion-layout: all 180ms cubic-bezier(0.2, 0, 0, 1);
  --motion-modal: transform 180ms cubic-bezier(0.16, 1, 0.3, 1), opacity 180ms cubic-bezier(0.16, 1, 0.3, 1);
  --motion-page: opacity 180ms cubic-bezier(0, 0, 0.2, 1);

  /* Z-Index */
  --z-base: 0;
  --z-raised: 10;
  --z-dropdown: 100;
  --z-sticky: 200;
  --z-overlay: 300;
  --z-modal: 400;
  --z-popover: 500;
  --z-toast: 600;
  --z-tooltip: 700;

  /* Breakpoint */
  --breakpoint-xs: 320px;
  --breakpoint-sm: 640px;
  --breakpoint-md: 768px;
  --breakpoint-lg: 1024px;
  --breakpoint-xl: 1280px;
  --breakpoint-2xl: 1536px;

  /* Accessibility */
  --focus-ring-width: 2px;
  --focus-ring-offset: 2px;
  --focus-ring-radius: 2px;
  --touch-target-min: 44px;

  /* Component / Button */
  --button-height-sm: 2rem;
  --button-height-md: 2.75rem;
  --button-height-lg: 3.25rem;
  --button-height-xl: 3.75rem;
  --button-padding-x-sm: 0.875rem;
  --button-padding-x-md: 1.25rem;
  --button-padding-x-lg: 1.75rem;
  --button-padding-x-xl: 2.25rem;
  --button-radius: 2px;
  --button-icon-size: 1.25rem;
  --button-gap: 0.5rem;

  /* Component / Card */
  --card-padding-sm: 1rem;
  --card-padding-md: 1.5rem;
  --card-padding-lg: 2.25rem;
  --card-padding-xl: 3rem;
  --card-radius: 2px;
  --card-border-width: 1px;
  --card-shadow: 2px 2px 0px #09090b;

  /* Component / Navigation */
  --nav-height: 4rem;
  --nav-padding-x: 1.5rem;
  --nav-gap: 2rem;
  --nav-item-height: 2.5rem;
  --nav-item-radius: 2px;

  /* Component / Badge */
  --badge-height-sm: 1.25rem;
  --badge-height-md: 1.625rem;
  --badge-padding-x: 0.5rem;
  --badge-radius: 1px;
  --badge-gap: 0.25rem;

  /* Component / Modal */
  --modal-width-sm: 400px;
  --modal-width-md: 560px;
  --modal-width-lg: 720px;
  --modal-width-xl: 960px;
  --modal-padding: 2rem;
  --modal-radius: 2px;
  --modal-shadow: 8px 8px 0px #09090b;

  /* Component / Tooltip */
  --tooltip-max-width: 240px;
  --tooltip-padding-x: 0.625rem;
  --tooltip-padding-y: 0.375rem;
  --tooltip-radius: 1px;

  /* Component / Input */
  --input-height-sm: 2.25rem;
  --input-height-md: 2.75rem;
  --input-height-lg: 3.25rem;
  --input-padding-x: 0.875rem;
  --input-padding-y: 0.625rem;
  --input-radius: 2px;
  --input-border-width: 1px;

  /* Component / Avatar */
  --avatar-ring-width: 2px;
  --avatar-ring-color: #ffffff;
  --avatar-group-overlap: -0.5rem;

  /* Component / Divider */
  --divider-width: 1px;
  --divider-spacing: 1.5rem;

  /* Component / Overlay */
  --overlay-opacity: 0.65;
  --overlay-blur: 0px;
  --overlay-radius: 0px;

  /* Responsive Layout */
  --mobile-page-padding: 1rem;
  --mobile-section-spacing: 3rem;
  --mobile-content-gap: 1.25rem;
  --mobile-grid-gap: 1rem;
  --desktop-page-padding: 3.5rem;
  --desktop-section-spacing: 5.5rem;
  --desktop-content-gap: 2.5rem;
  --desktop-grid-gap: 2rem;
}
